    fence_a(qa[0]);
    fence_a(qa[1]);
    wg_fence();
    wgmma_e4m3(sc, qa[0][0], qa[0][1], qa[0][2], qa[0][3], gdesc(kc_addr, LBO_K, SBO_K), 0);
    wgmma_e4m3(sc, qa[1][0], qa[1][1], qa[1][2], qa[1][3], gdesc(kc_addr + 2 * LBO_K, LBO_K, SBO_K), 1);
    wg_commit();
    wg_wait0();
    fence_regs(sc);
    fence_a(qa[0]);
    fence_a(qa[1]);
